// Build rule.json cleanly using Node.js to avoid double-escaping issues
const fs = require('fs');
const path = require('path');

// 1. find_rule for Home / Channel listing
function homeRule() {
  var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
  base = base.replace(/\/+$/, '');
  var ch = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && (MY_PARAMS.class || MY_PARAMS.fyclass)) ? (MY_PARAMS.class || MY_PARAMS.fyclass) : '20';
  var pg = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
  var reqUrl = base + '/api/list?channel=' + encodeURIComponent(ch) + '&page=' + encodeURIComponent(pg);

  var respStr = request(reqUrl);
  if (!respStr) {
    throw new Error('Bridge returned empty response from ' + reqUrl);
  }
  var json = JSON.parse(respStr);
  if (!json || !json.ok || !json.data) {
    throw new Error('Bridge error: ' + (json && json.error ? json.error : 'unknown'));
  }

  var items = json.data.items || [];
  var d = [];
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
      title: it.name || '',
      pic_url: it.pic || '',
      url: base + '/api/detail?id=' + encodeURIComponent(it.id),
      desc: it.continu || (it.year ? it.year + '' : ''),
      col_type: 'movie_3'
    });
  }
  setResult(d);
}

// 2. searchFind for Search
function searchRule() {
  var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
  base = base.replace(/\/+$/, '');
  var kw = (typeof KEYWORD !== 'undefined' && KEYWORD) ? KEYWORD : ((typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) ? MY_KEYWORD : '');
  if (!kw && typeof MY_URL !== 'undefined' && MY_URL) {
    var m = MY_URL.match(/[?&]key=([^&]+)/);
    if (m) kw = decodeURIComponent(m[1]);
  }
  var pg = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : ((typeof MY_SEARCH_PAGE !== 'undefined' && MY_SEARCH_PAGE) ? MY_SEARCH_PAGE : 1);
  var reqUrl = base + '/api/search?key=' + encodeURIComponent(kw) + '&page=' + encodeURIComponent(pg);

  var respStr = request(reqUrl);
  if (!respStr) {
    throw new Error('Bridge returned empty response from ' + reqUrl);
  }
  var json = JSON.parse(respStr);
  if (!json || !json.ok || !json.data) {
    throw new Error('Bridge search error: ' + (json && json.error ? json.error : 'unknown'));
  }

  var items = json.data.items || [];
  var d = [];
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    d.push({
      title: it.name || '',
      pic_url: it.pic || '',
      url: base + '/api/detail?id=' + encodeURIComponent(it.id),
      desc: it.continu || (it.year ? it.year + '' : ''),
      col_type: 'movie_3'
    });
  }
  setResult(d);
}

// 3. detail_find_rule for Detail & Episodes
function detailRule() {
  var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
  base = base.replace(/\/+$/, '');
  var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
  var id = '';
  var m = currentUrl.match(/[?&]id=([^&]+)/);
  if (m) {
    id = decodeURIComponent(m[1]);
  } else if (/^\d+$/.test(currentUrl)) {
    id = currentUrl;
  }
  if (!id) {
    throw new Error('Cannot extract video id from: ' + currentUrl);
  }

  var reqUrl = base + '/api/detail?id=' + encodeURIComponent(id);
  var respStr = request(reqUrl);
  if (!respStr) {
    throw new Error('Bridge detail returned empty response');
  }
  var json = JSON.parse(respStr);
  if (!json || !json.ok || !json.data) {
    throw new Error('Bridge detail error: ' + (json && json.error ? json.error : 'unknown'));
  }

  var data = json.data;
  var d = [];
  var cleanTitle = data.name || '动漫';

  // Rule 5: 剧名保护首卡
  d.push({
    title: '剧名：' + cleanTitle,
    desc: (data.year ? data.year + ' ' : '') + (data.area ? data.area + ' ' : '') + (data.type ? data.type : ''),
    pic_url: data.pic || '',
    url: currentUrl,
    col_type: 'pic_1_card'
  });

  if (data.content) {
    d.push({
      title: data.content,
      col_type: 'text_1'
    });
  }

  // Lazy function definition
  var lazyFnStr = (function() {
    var base = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : '';
    var targetUrl = input;
    if (base) {
      base = base.replace(/\/+$/, '');
      var pathIdx = targetUrl.indexOf('/api/');
      if (pathIdx !== -1) {
        targetUrl = base + targetUrl.substring(pathIdx);
      }
    }
    var res = JSON.parse(request(targetUrl));
    if (!res || !res.ok || !res.data) {
      throw new Error(res && res.error ? res.error : 'Failed to resolve play URL');
    }
    var playData = res.data;
    var defIdx = playData.default || 0;
    var variant = (playData.list && playData.list[defIdx]) ? playData.list[defIdx] : (playData.list && playData.list[0]);
    if (!variant || !variant.url) {
      throw new Error('No valid stream URL found');
    }
    var headers = variant.headers || {};
    var headerPairs = [];
    for (var k in headers) {
      if (headers.hasOwnProperty(k) && headers[k]) {
        headerPairs.push(k + '@' + headers[k]);
      }
    }
    if (headerPairs.length > 0) {
      return variant.url + ';{' + headerPairs.join('&&') + '}';
    }
    return variant.url;
  }).toString();

  var parts = data.parts || [];
  for (var i = 0; i < parts.length; i++) {
    var group = parts[i];
    var groupName = group.play_zh || group.play || ('线路 ' + (i + 1));
    d.push({
      title: '【' + groupName + '】',
      col_type: 'text_1'
    });
    var eps = group.part || [];
    for (var j = 0; j < eps.length; j++) {
      var epName = eps[j];
      var playEndpoint = base + '/api/play?id=' + encodeURIComponent(id) + '&part=' + encodeURIComponent(epName) + '&play=' + encodeURIComponent(group.play || '');
      var lazyUrl = playEndpoint + '@lazyRule=.js:(' + lazyFnStr + ')()';
      d.push({
        title: epName,
        url: lazyUrl,
        col_type: 'text_3'
      });
    }
  }
  setResult(d);
}

const rule = {
  title: "动漫共和国",
  author: "MoZhi",
  version: 1,
  url: "http://127.0.0.1:18002/api/list?[REDACTED_QUERY]",
  class_name: "日漫&国漫&剧场&美漫&特摄&少儿&动态漫&猜你想看",
  class_url: "20&21&22&23&25&32&26&27",
  find_rule: "js:(" + homeRule.toString() + ")()",
  search_url: "http://127.0.0.1:18002/api/search?[REDACTED_QUERY]",
  searchFind: "js:(" + searchRule.toString() + ")()",
  detail_find_rule: "js:(" + detailRule.toString() + ")()"
};

fs.writeFileSync(path.join(__dirname, '..', 'rule.json'), JSON.stringify(rule, null, 2), 'utf-8');
console.log('rule.json successfully written!');

